import pandas as pd

# Step1: Filter rows where Date is between 1880 and 1910 (inclusive)
filtered_df = df[(df['Date'] >= 1880) & (df['Date'] <= 1910)]

# Step2: Filter rows where Notes contain "Banat"
filtered_df = filtered_df[filtered_df['Notes'].str.contains("Banat", case=False, na=False)]

# Step3: Extract the "Population Romania" values
population_values = filtered_df['Population Romania']

# Step4: Convert to numeric, handling ranges
def parse_population(value):
    if isinstance(value, str):
        if '–' in value:
            low, high = map(int, value.replace(',', '').split('–'))
            return (low + high) / 2
        else:
            return int(value.replace(',', ''))
    else:
        return float(value)

numeric_populations = population_values.apply(parse_population)

# Step5: Compute the average
average_population = numeric_populations.mean()

# Step6: Round to two decimal places
final_answer_value = round(average_population, 2)

